class Solution:
    def numEquivDominoPairs(self, dominoes: list[list[int]]) -> int:
        counts = [0] * 100
        total = 0
        for a, b in dominoes:
            key = min(a, b) * 10 + max(a, b)
            total += counts[key]
            counts[key] += 1
        return total

class Solution {
public:
    int numEquivDominoPairs(vector<vector<int>>& dominoes) {
        vector<int> counts(100, 0);
        int total = 0;
        for (const auto& d : dominoes) {
            int key = min(d[0], d[1]) * 10 + max(d[0], d[1]);
            total += counts[key];
            counts[key]++;
        }
        return total;
    }
};

class Solution {
    public int numEquivDominoPairs(int[][] dominoes) {
        int[] counts = new int[100];
        int total = 0;
        for (int[] d : dominoes) {
            int key = Math.min(d[0], d[1]) * 10 + Math.max(d[0], d[1]);
            total += counts[key];
            counts[key]++;
        }
        return total;
    }
}

var numEquivDominoPairs = function(dominoes) {
    const counts = new Array(100).fill(0);
    let total = 0;
    for (const [a, b] of dominoes) {
        const key = Math.min(a, b) * 10 + Math.max(a, b);
        total += counts[key];
        counts[key]++;
    }
    return total;
};
